#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int prices[10000];
    for (int i = 0; i < n; i++) scanf("%d", &prices[i]);
    int minPrice = prices[0];
    int maxProfit = 0;
    for (int i = 1; i < n; i++) {
        if (prices[i] - minPrice > maxProfit) maxProfit = prices[i] - minPrice;
        if (prices[i] < minPrice) minPrice = prices[i];
    }
    printf("%d\n", maxProfit);
    return 0;
}

#include <stdio.h>

static void reverse(int arr[], int lo, int hi) {
    while (lo < hi) {
        int tmp = arr[lo];
        arr[lo] = arr[hi];
        arr[hi] = tmp;
        lo++;
        hi--;
    }
}

int main(void) {
    int n, k;
    scanf("%d %d", &n, &k);
    int arr[1000];
    for (int i = 0; i < n; i++) scanf("%d", &arr[i]);
    k = k % n;
    reverse(arr, 0, n - 1);
    reverse(arr, 0, k - 1);
    reverse(arr, k, n - 1);
    for (int i = 0; i < n; i++) {
        if (i > 0) printf(" ");
        printf("%d", arr[i]);
    }
    printf("\n");
    return 0;
}

