#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    int arr[1000];
    long long prefix[1001];
    prefix[0] = 0;
    for (int i = 0; i < n; i++) {
        scanf("%d", &arr[i]);
        prefix[i + 1] = prefix[i] + arr[i];
    }
    int q;
    scanf("%d", &q);
    for (int i = 0; i < q; i++) {
        int l, r;
        scanf("%d %d", &l, &r);
        printf("%lld\n", prefix[r + 1] - prefix[l]);
    }
    return 0;
}
